/**
 * Image registry. Every photograph on the site is described here once:
 * its responsive widths (generated by scripts/prepare-images.py), its intrinsic
 * size, and named focal points in fractions of the frame. The focal points
 * drive the camera moves, the spotlight reveals and the loupe.
 */

export type FocalPoint = { x: number; y: number };

export type MediaKey =
  | "brilliance"
  | "emerald"
  | "pearl"
  | "solitaire"
  | "emerald-halo"
  | "emerald-shoulder"
  | "pearl-portrait"
  | "pearl-macro";

export type Media = {
  key: MediaKey;
  width: number;
  height: number;
  widths: number[];
  /** Colour shown while the image loads; sampled from the photograph. */
  tone: string;
  focal: Record<string, FocalPoint>;
};

